import unittest
import pytest
from candidate import below_zero


class TestBelowZero(unittest.TestCase):
    def test_normal_positive_operations(self):
        self.assertFalse(below_zero([10, 20, 30]))

    def test_negative_first_operation(self):
        self.assertTrue(below_zero([-5, 10, 20]))

    def test_negative_after_positive_operations(self):
        self.assertTrue(below_zero([5, 15, -30, 10]))

    def test_no_negative_operations(self):
        self.assertFalse(below_zero([5, 10, 15, 20]))

    def test_empty_operations(self):
        self.assertFalse(below_zero([]))

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            below_zero(None)

    def test_non_iterable_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            below_zero(123)

    def test_non_int_in_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            below_zero([5, "a", 10])

    def test_float_operations(self):
        self.assertTrue(below_zero([1.5, -2.5]))

    def test_tuple_operations(self):
        self.assertFalse(below_zero((3, 4, 5)))

    def test_generator_operations(self):
        gen = (i for i in [2, -5, 3])
        self.assertTrue(below_zero(gen))

    def test_generator_early_stop(self):
        class YieldCounterGenerator:
            def __init__(self, data):
                self.data = data
                self.counter = 0

            def __iter__(self):
                return self

            def __next__(self):
                if self.counter >= len(self.data):
                    raise StopIteration
                value = self.data[self.counter]
                self.counter += 1
                return value

        generator = YieldCounterGenerator([10, -15, 20])
        result = below_zero(generator)
        self.assertTrue(result)
        self.assertEqual(generator.counter, 2)

    def test_string_operations_raises_type_error(self):
        with self.assertRaises(TypeError):
            below_zero("123")

    def test_list_with_none_element_raises_type_error(self):
        with self.assertRaises(TypeError):
            below_zero([1, None, 2])

    def test_large_operations_no_negative(self):
        large_list = [i for i in range(1, 1000)]
        self.assertFalse(below_zero(large_list))

    def test_boundary_zero_only(self):
        self.assertFalse(below_zero([0, 0, 0]))

    def test_operations_with_zero_and_negative(self):
        self.assertTrue(below_zero([0, 0, -1, 5]))


if __name__ == "__main__":
    unittest.main()
